:root{--ink:#172b4d;--muted:#64748b;--line:#dbe4ef;--gold:#f4b400}*{box-sizing:border-box}body{margin:0;background:linear-gradient(135deg,#f5f8fc,#fffdf5);font-family:Inter,system-ui,sans-serif;color:var(--ink)}.wrap{max-width:1100px;margin:auto;padding:30px 18px}.head{display:flex;justify-content:space-between;gap:20px;align-items:end;margin-bottom:18px}.kicker{color:#0f766e;font-size:11px;font-weight:900;letter-spacing:.15em;text-transform:uppercase}.head h1{margin:7px 0;font-size:29px}.head p{margin:0;color:var(--muted);font-size:13px}.actions{display:flex;gap:8px;flex-wrap:wrap}.actions a,.save{display:inline-flex;align-items:center;gap:8px;border-radius:10px;padding:11px 14px;font-size:12px;font-weight:900;text-decoration:none}.actions a{border:1px solid var(--line);background:#fff;color:var(--ink)}.save{border:0;background:var(--gold);color:#172033;cursor:pointer}.grid{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:18px}.card{border:1px solid var(--line);border-radius:18px;background:#fff;box-shadow:0 14px 34px #1d2b5714;overflow:hidden}.card-head{padding:18px 21px;border-bottom:1px solid #edf1f6;background:#f8fbff}.card-head h2{margin:0;font-size:16px}.card-head p{margin:5px 0 0;color:var(--muted);font-size:11px}.body{padding:21px}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.wide{grid-column:1/-1}label.field{display:block;color:#34425a;font-size:11px;font-weight:900}.field input{display:block;width:100%;margin-top:6px;border:1px solid #ccd7e5;border-radius:10px;padding:12px}.field input:focus{outline:0;border-color:#3275c7;box-shadow:0 0 0 4px #e4efff}.select2-container{width:100%!important;margin-top:6px}.select2-container--default .select2-selection--single{height:44px;border:1px solid #ccd7e5;border-radius:10px}.select2-container--default .select2-selection--single .select2-selection__rendered{line-height:42px}.client-option{display:flex;align-items:center;gap:8px}.client-option img{width:30px;height:30px;object-fit:contain;border-radius:7px;background:#f1f5f9}.drop{display:grid;place-items:center;min-height:150px;margin-top:6px;border:1.5px dashed #9db1c8;border-radius:14px;background:#fbfdff;color:#64748b;text-align:center;cursor:pointer}.drop:hover,.drop.over{border-color:#0f766e;background:#ecfdf5}.drop i{font-size:24px;color:#0f766e}.drop strong{display:block;margin-top:7px;color:var(--ink)}.drop small{display:block;margin-top:5px;font-weight:400}.drop input{display:none}.preview,.existing{display:grid;gap:7px;margin-top:10px}.file{display:flex;align-items:center;gap:8px;border:1px solid #e5ebf2;border-radius:8px;background:#f8fafc;padding:9px;font-size:11px}.file i{color:#0f766e}.file a{margin-left:auto;color:#1d4ed8}.footer{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-top:22px;padding-top:17px;border-top:1px solid #edf1f6}.muted{color:#94a3b8;font-size:12px}@media(max-width:800px){.head{align-items:start;flex-direction:column}.grid{grid-template-columns:1fr}}@media(max-width:600px){.fields{grid-template-columns:1fr}.wide{grid-column:auto}.footer{align-items:stretch;flex-direction:column-reverse}}
</style></head><body><main class="wrap"><header class="head"><div><div class="kicker"><i class="fa-solid fa-folder-open"></i> Centre projets Finéa</div><h1>Modifier le projet</h1><p>Actualisez le client, les informations et les documents du projet.</p></div><div class="actions"><a href="offres/liste.php"><i class="fa-solid fa-arrow-left"></i> Retour</a><a href="offres/dashboard.php"><i class="fa-solid fa-gauge-high"></i> Dashboard</a></div></header><form action="request/modifier_offre.php" method="post" enctype="multipart/form-data" id="form"><input type="hidden" name="id_offre" value="<?=$id?>"><div class="grid"><section class="card"><div class="card-head"><h2><i class="fa-solid fa-pen-to-square"></i> Informations du projet</h2><p>Le numéro projet est conservé automatiquement.</p></div><div class="body"><div class="fields"><label class="field">Numéro projet<input readonly value="<?=htmlspecialchars((string)($offre['num_offre']??''),ENT_QUOTES,'UTF-8')?>"></label><label class="field">Date du projet<input type="date" name="date_offre" required value="<?=htmlspecialchars($date,ENT_QUOTES,'UTF-8')?>"></label><label class="field wide">Intitulé / référence<input name="reference_offre" required value="<?=htmlspecialchars((string)($offre['reference_offre']??''),ENT_QUOTES,'UTF-8')?>"></label><label class="field">Superviseur interne<input name="commercial_dedie" required value="<?=htmlspecialchars((string)($offre['commercial_dedie']??''),ENT_QUOTES,'UTF-8')?>"></label><label class="field">Date de création<input type="date" name="date_creat_offre" required value="<?=htmlspecialchars($created,ENT_QUOTES,'UTF-8')?>"></label><label class="field wide">Client du projet *<select id="client_id" name="client_id" required><option value="">Rechercher par client ou NCC...</option><?php foreach($clients as $client):?><option value="<?= (int)$client['id_client']?>" data-ncc="<?=htmlspecialchars((string)($client['ncc']??''),ENT_QUOTES,'UTF-8')?>" data-logo="<?=htmlspecialchars((string)($client['logo_client']??''),ENT_QUOTES,'UTF-8')?>" <?=((int)($offre['client_id']??0)===(int)$client['id_client'])?'selected':''?>><?=htmlspecialchars((string)$client['nom_client'],ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></label><label class="field wide">Ajouter des documents<label class="drop" id="drop"><span><i class="fa-solid fa-cloud-arrow-up"></i><strong>Déposez les fichiers ici</strong><small>ou cliquez pour les sélectionner</small></span><input id="files" name="offre_files[]" type="file" multiple></label><div id="preview" class="preview"></div></label></div><div class="footer"><a class="actions" href="offres/liste.php"><span><i class="fa-solid fa-xmark"></i> Annuler</span></a><button class="save"><i class="fa-solid fa-floppy-disk"></i> Enregistrer les modifications</button></div></div></section><aside class="card"><div class="card-head"><h2><i class="fa-solid fa-paperclip"></i> Documents existants</h2><p><?=count($files)?> document(s)</p></div><div class="body"><div class="existing"><?php if(!$files):?><span class="muted">Aucun document joint.</span><?php else:foreach($files as $file):$path=str_replace('../','',(string)($file['file_path']??''));?><div class="file"><i class="fa-solid fa-file-lines"></i><span><?=htmlspecialchars((string)($file['file_name']??'Document'),ENT_QUOTES,'UTF-8')?></span><a href="<?=htmlspecialchars($path,ENT_QUOTES,'UTF-8')?>" target="_blank" download><i class="fa-solid fa-download"></i></a></div><?php endforeach;endif;?></div></div></aside></div></form></main><script src="https://code.jquery.com/jquery-3.7.1.min.js"></script><script src="https://cdn.jsdelivr.net/npm/select2@4.1.0-rc.0/dist/js/select2.min.js"></script><script>(()=>{const select=document.querySelector('#client_id');const render=item=>{if(!item.id)return item.text;const logo=item.element?.dataset?.logo;const ncc=item.element?.dataset?.ncc;const node=jQuery('<span class="client-option"><span></span></span>');if(logo)node.prepend(jQuery('<img>').attr({src:'../uploads/logos_clients/'+logo,alt:''}));node.find('span').text(ncc?item.text+' · NCC '+ncc:item.text);return node;};jQuery(select).select2({placeholder:'Rechercher par client ou NCC...',allowClear:true,width:'100%',templateResult:render,templateSelection:render});const input=document.querySelector('#files'),drop=document.querySelector('#drop'),preview=document.querySelector('#preview');const show=files=>{preview.innerHTML='';Array.from(files||[]).forEach(file=>{const row=document.createElement('div');row.className='file';row.innerHTML='<i class="fa-solid fa-file"></i><span></span>';row.querySelector('span').textContent=file.name+' · '+Math.ceil(file.size/1024)+' Ko';preview.appendChild(row);});};input.addEventListener('change',()=>show(input.files));['dragenter','dragover'].forEach(e=>drop.addEventListener(e,x=>{x.preventDefault();drop.classList.add('over')}));['dragleave','drop'].forEach(e=>drop.addEventListener(e,x=>{x.preventDefault();drop.classList.remove('over')}));drop.addEventListener('drop',e=>{const dt=new DataTransfer();Array.from(e.dataTransfer.files).forEach(f=>dt.items.add(f));input.files=dt.files;show(input.files)});})();</script></body></html>
